mapper.update:
SET ANSI_NULLS ON; SET QUOTED_IDENTIFIER ON; SET ANSI_PADDING ON; SET ANSI_WARNINGS ON;
SET CONCAT_NULL_YIELDS_NULL ON; SET ARITHABORT ON; SET NUMERIC_ROUNDABORT OFF;

IF @@TRANCOUNT=0
BEGIN
    DECLARE @implicitTransactions INT=(@@OPTIONS & 2);
    SET IMPLICIT_TRANSACTIONS OFF;
    BEGIN TRANSACTION;
    IF @implicitTransactions=2 SET IMPLICIT_TRANSACTIONS ON;
END;

mapper.select:
DECLARE @r INT,@k NVARCHAR(255)=CONCAT('tyco-packing-user-',#{owner});
EXEC @r=sys.sp_getapplock @Resource=@k,@LockMode='Exclusive',@LockOwner='Transaction',@LockTimeout=10000;
SELECT @r AS returnCode,@@TRANCOUNT AS transactionCount,XACT_STATE() AS transactionState,
       @@SPID AS sessionId,DB_NAME() AS databaseName;

DECLARE @r INT;
EXEC @r=sys.sp_getapplock @Resource='tyco-packing-codes',@LockMode='Exclusive',@LockOwner='Transaction',@LockTimeout=10000;
SELECT @r AS returnCode,@@TRANCOUNT AS transactionCount,XACT_STATE() AS transactionState,
       @@SPID AS sessionId,DB_NAME() AS databaseName;

mapper.update:
UPDATE dbo.tyco_packing_session SET status='PACKED',is_draft=0,version=version+1,
    reviewed_at=SYSDATETIME(),reviewed_by=#{user},is_tail_box=#{tailBox},packed_quantity=#{packedQuantity}
WHERE id=#{id} AND status='SCANNING'
